.header_top .header_buttons {
	display: flex;
	padding-right: 0;
	margin-right: -5px;
}

.language_link_wrapper {
	display: flex;
}

.language_link_wrapper .language_link.button {
	color: var(--navbar_text_color);
	color: #000 !important;
	background: var(--navbar_color) url(https://www.masspowerchoice.com/wp-content/themes/mpc2024/img/Google_Translate_logo_32.png) no-repeat left 10px center;
	background-color: #fff;
	opacity: 1;
	background-size: 12px 12px;
	padding-left: 24px !important;
	cursor: pointer;
	border: 1px solid var(--navbar_color);
	transition: all .25s ease;
}

.language_link_wrapper .language_link.button:hover {
	color: #000;
	opacity: .9 !important;
}

.language_select_popup {
	display: none;
	position: fixed;
	z-index: 7777;
	background: #fff;
	padding: 0;
	max-width: 800px;
	overflow: auto;
	top: 50%;
	left: 50%;
	border: 2px solid var(--navbar_color);
	transform: translateX(-50%) translateY(-50%);
	border-radius: 15px;
}

.language_select_popup,
.language_options_wrapper {
	max-height: 80vh;
	overflow: hidden;
}

.language_select_popup.active {
	display: block;
}

.language_options_wrapper {
	overflow: auto;
	width: calc(100% - 80px);
	padding: 40px 40px 80px 40px;
}

.lang_link_wrapper {
	display: block;
	column-count: 3;
	column-gap: 50px;
}

.lang_link_wrapper.more_languages {
	margin-top: 30px;
	padding-top: 30px;
	padding-bottom: 80px;
	border-top: 1px solid #000;
}

.lang_link_wrapper .lang_link {
	width: 100%;
	text-align: left;
	height: 40px;
	line-height: 40px;
	white-space: nowrap;
}

.close_language_popup {
	cursor: pointer;
	position: fixed;
	top: 2px;
	right: 2px;
	background: var(--navbar_color);
	color: var(--navbar_text_color);
	font-size: 24px;
	font-weight: bold;
	height: 24px;
	width: 24px;
	line-height: 24px;
	border-radius: 24px;
	text-align: center;
}


@media screen and (max-width: 799px) {

	.language_link_wrapper {
		display: inline-block;
	}

	.lang_link_wrapper {
		column-count: 2;
	}

}


/* 1. Target pages hosted on translate.goog or googleusercontent proxy */
html[lang*="-x-mt"],
html[class*="translated"],
/* Targets when Google injects elements with translate.goog attributes */
[data-gt-orig-xmlns],
[data-lang] {
  /* Hides your language link wrapper */
  .language_link_wrapper {
	display: none !important;
  }
}






document.addEventListener('click', function(e) {
  if (e.target.closest('.language_link.button')) {
	// Open translation modal logic
	jQuery(".language_select_popup").toggleClass("active");
	jQuery("#modal_bg").toggleClass("active");
	jQuery("body").addClass("noscroll");
	return false;
  }
});

jQuery(document).ready(function() {

	jQuery('#modal_bg, .close_language_popup').click(function() {
		jQuery(".language_select_popup").removeClass("active");
		jQuery("#modal_bg").removeClass("active");
		jQuery("body").removeClass("noscroll");
	});

});







