	border-top: 1px solid rgba(255,255,255,.5);
	border-bottom: 1px solid rgba(255,255,255,.5);
	margin-top: 10px;
	background: rgba(255,255,255,.3);
}

#access .header_buttons a {
	margin: 7px 5px !important;
}

#access .header_buttons a.button {
	font-size: 12px;
	padding: 3px 5px;
