@media screen and (min-width: 800px) and (max-width: 1023px) {

	.header_translate {
		padding-left: 20px;
	}
}

@media screen and (min-width: 800px) {

	.header_top {
		display: flex;
	}
	.header_top > div {
		width: 50%;
	}
	.header_top .header_buttons {
		text-align: right;
		margin-top: 3px;
	}

}





